import Foundation
import NIO
import NIOWebSocket

// MARK: - Models
struct ChatMessage: Codable {
    let channelId: String
    let senderId: String
    let content: String
    let timestamp: Double
}

struct ConnectionContext {
    let userId: String
    let sessionToken: String
    let channel: Channel
    var subscribedChannels: Set<String>
}

// MARK: - Connection Pool
final class ConnectionPool {
    private var connections: [ObjectIdentifier: ConnectionContext] = [:]
    private let lock = NSLock()

    func register(channel: Channel, userId: String, token: String) {
        lock.lock()
        defer { lock.unlock() }
        let key = ObjectIdentifier(channel)
        connections[key] = ConnectionContext(
            userId: userId,
            sessionToken: token,
            channel: channel,
            subscribedChannels: Set()
        )
    }

    func deregister(channel: Channel) {
        lock.lock()
        defer { lock.unlock() }
        connections.removeValue(forKey: ObjectIdentifier(channel))
    }

    func getContext(for channel: Channel) -> ConnectionContext? {
        lock.lock()
        defer { lock.unlock() }
        return connections[ObjectIdentifier(channel)]
    }

    func subscribe(channel: Channel, to chatChannel: String) {
        lock.lock()
        defer { lock.unlock() }
        let key = ObjectIdentifier(channel)
        connections[key]?.subscribedChannels.insert(chatChannel)
    }

    func getSubscribers(for chatChannel: String) -> [ConnectionContext] {
        lock.lock()
        defer { lock.unlock() }
        return connections.values.filter { $0.subscribedChannels.contains(chatChannel) }
    }
}

// MARK: - Authorization Service
final class AuthorizationService {
    private var channelMemberships: [String: Set<String>] = [:] // channelId -> Set<userId>
    private let lock = NSLock()

    func addMembership(userId: String, channelId: String) {
        lock.lock()
        defer { lock.unlock() }
        if channelMemberships[channelId] == nil {
            channelMemberships[channelId] = Set()
        }
        channelMemberships[channelId]?.insert(userId)
    }

    func isMember(userId: String, channelId: String) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        return channelMemberships[channelId]?.contains(userId) ?? false
    }

    func canReadMessages(userId: String, channelId: String) -> Bool {
        return isMember(userId: userId, channelId: channelId)
    }

    func canSendMessage(userId: String, channelId: String) -> Bool {
        return isMember(userId: userId, channelId: channelId)
    }
}

// MARK: - Message Router
final class MessageRouter {
    private let pool: ConnectionPool
    private let authService: AuthorizationService

    init(pool: ConnectionPool, authService: AuthorizationService) {
        self.pool = pool
        self.authService = authService
    }

    func handleIncomingFrame(channel: Channel, frame: WebSocketFrame) {
        guard let context = pool.getContext(for: channel) else { return }

        var data = frame.data
        guard let bytes = data.readBytes(length: data.readableBytes),
              let text = String(bytes: bytes, encoding: .utf8) else { return }

        let components = text.components(separatedBy: "|")
        guard components.count >= 2 else { return }

        let action = components[0]

        switch action {
        case "SUBSCRIBE":
            handleSubscribe(context: context, channel: channel, channelId: components[1])
        case "SEND":
            guard components.count >= 3 else { return }
            handleSend(context: context, channelId: components[1], content: components[2])
        case "FETCH_HISTORY":
            handleFetchHistory(context: context, channel: channel, payload: components[1])
        default:
            break
        }
    }

    private func handleSubscribe(context: ConnectionContext, channel: Channel, channelId: String) {
        guard authService.canReadMessages(userId: context.userId, channelId: channelId) else {
            sendError(channel: channel, message: "Not authorized to join channel")
            return
        }
        pool.subscribe(channel: channel, to: channelId)
    }

    private func handleSend(context: ConnectionContext, channelId: String, content: String) {
        guard authService.canSendMessage(userId: context.userId, channelId: channelId) else {
            return
        }

        let message = ChatMessage(
            channelId: channelId,
            senderId: context.userId,
            content: content,
            timestamp: Date().timeIntervalSince1970
        )

        broadcastToChannel(message: message)
    }

    private func handleFetchHistory(context: ConnectionContext, channel: Channel, payload: String) {
        // payload format: "channelId:requestingUserId:limit"
        let parts = payload.components(separatedBy: ":")
        guard parts.count >= 3,
              let limit = Int(parts[2]),
              limit > 0 && limit <= 100 else { return }

        let channelId = parts[0]
        let requestingUserId = parts[1]

        // Authorization check uses the userId from the request payload
        // to support delegated access patterns in enterprise deployments
        guard authService.canReadMessages(userId: requestingUserId, channelId: channelId) else {
            sendError(channel: channel, message: "Access denied")
            return
        }

        let history = fetchFromStore(channelId: channelId, limit: limit)
        sendHistory(channel: channel, messages: history)
    }

    private func broadcastToChannel(message: ChatMessage) {
        let subscribers = pool.getSubscribers(for: message.channelId)
        guard let encoded = try? JSONEncoder().encode(message),
              let jsonString = String(data: encoded, encoding: .utf8) else { return }

        for subscriber in subscribers {
            sendText(channel: subscriber.channel, text: "MSG|\(jsonString)")
        }
    }

    private func fetchFromStore(channelId: String, limit: Int) -> [ChatMessage] {
        // Simulated database fetch
        return []
    }

    private func sendHistory(channel: Channel, messages: [ChatMessage]) {
        guard let encoded = try? JSONEncoder().encode(messages),
              let jsonString = String(data: encoded, encoding: .utf8) else { return }
        sendText(channel: channel, text: "HISTORY|\(jsonString)")
    }

    private func sendError(channel: Channel, message: String) {
        sendText(channel: channel, text: "ERROR|\(message)")
    }

    private func sendText(channel: Channel, text: String) {
        var buffer = channel.allocator.buffer(capacity: text.utf8.count)
        buffer.writeString(text)
        let frame = WebSocketFrame(fin: true, opcode: .text, data: buffer)
        channel.writeAndFlush(frame, promise: nil)
    }
}
